steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        issues(filter: {
          title: {contains: \"login redirect\"},
          createdAt: {between: [\"2024-09-10\", \"2024-09-11\"]}
        }) {
          nodes {
            id
            title
            identifier
            team { name }
            createdAt
            assignee { id name }
            creator { id name }
          }
        }
      }
    "
  }'
